import { describe, it, expect } from 'vitest';
import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import ExcelJS from 'exceljs';
import * as XLSX from 'xlsx';
import { strFromU8 } from 'fflate';
import { Workbook } from '../src/index';

/**
 * The README promises that data validations, conditional formatting, tables,
 * images, charts, pivot tables and comments are *preserved, not created*.
 *
 * The fixtures in `test/fixtures/preserve/` are generated by
 * `scripts/generate-preserve-fixtures.mjs` (deterministic — see the script
 * header). They exist only to give this file the rich parts real files never
 * showed up in `test/fixtures/real/`.
 */
const here = dirname(fileURLToPath(import.meta.url));
const DIR = join(here, 'fixtures', 'preserve');

/** Parts a workbook may legitimately rewrite when a worksheet is added. */
const REGISTRATION_PARTS = new Set([
  '[Content_Types].xml',
  'xl/workbook.xml',
  'xl/_rels/workbook.xml.rels',
]);

interface Fixture {
  file: string;
  /** Sheet names, for the cross-reader assertions. */
  sheets: string[];
  /**
   * The "rich" parts this file exists for: everything the README promises is
   * preserved. They must survive both a cell edit and an added worksheet, and
   * must never be silently dropped.
   */
  richParts: string[];
  /**
   * Sheet-local features, keyed by the worksheet part that owns them. These
   * live *inside* the part sheet-lite rewrites, so byte-identity cannot prove
   * them: they are asserted as surviving substrings of the re-serialized XML.
   */
  inSheet: Record<string, string[]>;
}

const FIXTURES: Fixture[] = [
  {
    file: 'validations-and-conditional-formatting.xlsx',
    sheets: ['Data'],
    // NOTE: `xl/styles.xml` is deliberately absent — a style edit is allowed
    // (and expected) to rewrite it. Everything else must survive.
    richParts: ['xl/sharedStrings.xml', 'xl/theme/theme1.xml'],
    inSheet: {
      'xl/worksheets/sheet1.xml': [
        '<dataValidations',
        '<dataValidation type="list"',
        '<dataValidation type="whole"',
        '<conditionalFormatting',
        'type="cellIs"',
        'type="colorScale"',
        '<mergeCell ref="A7:B7"',
        '<cols>',
        'x14ac:dyDescent',
      ],
    },
  },
  {
    file: 'table-and-comments.xlsx',
    sheets: ['Sales'],
    richParts: [
      'xl/tables/table1.xml',
      'xl/comments1.xml',
      'xl/drawings/vmlDrawing1.vml',
      'xl/worksheets/_rels/sheet1.xml.rels',
    ],
    inSheet: {
      'xl/worksheets/sheet1.xml': [
        '<tableParts',
        '<legacyDrawing',
        '<mergeCell ref="E1:F1"',
        'x14ac:dyDescent',
      ],
    },
  },
  {
    file: 'image-and-chart.xlsx',
    sheets: ['Data'],
    richParts: [
      'xl/media/image1.png',
      'xl/drawings/drawing1.xml',
      'xl/drawings/_rels/drawing1.xml.rels',
      'xl/charts/chart1.xml',
      'xl/charts/_rels/chart1.xml.rels',
      'xl/charts/colors1.xml',
      'xl/charts/style1.xml',
      'xl/worksheets/_rels/sheet1.xml.rels',
    ],
    inSheet: {
      'xl/worksheets/sheet1.xml': ['<drawing ', 'x14ac:dyDescent'],
    },
  },
  {
    file: 'pivot-table.xlsx',
    sheets: ['Raw', 'Summary'],
    richParts: [
      'xl/pivotTables/pivotTable1.xml',
      'xl/pivotCache/pivotCacheDefinition1.xml',
      'xl/pivotCache/pivotCacheRecords1.xml',
      'xl/pivotCache/_rels/pivotCacheDefinition1.xml.rels',
      'xl/worksheets/_rels/sheet2.xml.rels',
    ],
    // The pivot lives entirely outside the worksheet parts.
    inSheet: {},
  },
];

const eq = (a: Uint8Array, b: Uint8Array): boolean => Buffer.from(a).equals(Buffer.from(b));

/** Names actually present on disk — guards the manifest against a stale test. */
const onDisk = existsSync(DIR)
  ? readdirSync(DIR)
      .filter((name) => name.endsWith('.xlsx'))
      .sort()
  : [];

const bytesOf = (file: string): Uint8Array => new Uint8Array(readFileSync(join(DIR, file)));

/** Names of parts that differ between two part stores (missing counts as changed). */
function changedParts(before: ReturnType<Workbook['parts']>, after: ReturnType<Workbook['parts']>): string[] {
  const out: string[] = [];
  for (const name of before.names()) {
    if (!after.has(name) || !eq(before.get(name)!, after.get(name)!)) out.push(name);
  }
  return out;
}

function addedParts(before: ReturnType<Workbook['parts']>, after: ReturnType<Workbook['parts']>): string[] {
  return after.names().filter((name) => !before.has(name));
}

/** A representative edit: a cell value, a style change and a new merge. */
function representativeEdit(wb: Workbook): { partName: string } {
  const ws = wb.worksheets[0]!;
  ws.getCell('ZZ100').value = 'sheet-lite preservation probe';
  ws.getCell('D9').value = 1234.5;
  ws.getCell('A1').font = { bold: true, color: 'FF9C0006' };
  ws.getCell('A1').fill = { type: 'pattern', pattern: 'solid', fgColor: 'FFFFEB84' };
  ws.mergeCells('H9:J9');
  return { partName: ws.partName };
}

/** ExcelJS's `load` typings use a legacy global `Buffer` interface. */
type ExcelLoadInput = Parameters<ExcelJS.Workbook['xlsx']['load']>[0];
async function loadInExcelJs(data: Uint8Array): Promise<ExcelJS.Workbook> {
  const ej = new ExcelJS.Workbook();
  await ej.xlsx.load(data as unknown as ExcelLoadInput);
  return ej;
}

/** Independent readers must both accept the bytes we produced. */
async function expectReReadable(out: Uint8Array, sheets: string[]): Promise<void> {
  const sjs = XLSX.read(out, { type: 'buffer' });
  expect([...sjs.SheetNames].sort()).toEqual([...sheets].sort());

  const ejs = await loadInExcelJs(out);
  expect(ejs.worksheets.map((sheet) => sheet.name).sort()).toEqual([...sheets].sort());
}

describe('preservation fixtures — the corpus is present and honest', () => {
  it('has every fixture the manifest declares, and no stale manifest entry', () => {
    expect(onDisk).toEqual(FIXTURES.map((f) => f.file).sort());
  });

  for (const fixture of FIXTURES) {
    it(`${fixture.file}: really contains the parts it is here to protect`, () => {
      const parts = Workbook.read(bytesOf(fixture.file)).parts();
      for (const part of fixture.richParts) {
        expect(parts.has(part), `fixture part missing: ${part}`).toBe(true);
      }
      for (const [sheetPart, markers] of Object.entries(fixture.inSheet)) {
        expect(parts.has(sheetPart), `fixture sheet part missing: ${sheetPart}`).toBe(true);
        const xml = strFromU8(parts.get(sheetPart)!);
        for (const marker of markers) {
          expect(xml, `${sheetPart} lacks ${marker}`).toContain(marker);
        }
      }
    });
  }
});

describe('preservation — nothing changed returns the original bytes', () => {
  for (const fixture of FIXTURES) {
    it(`${fixture.file}: open + read + write is byte-for-byte the same file`, () => {
      const bytes = bytesOf(fixture.file);
      const wb = Workbook.read(bytes);

      expect(wb.sheetNames).toEqual(fixture.sheets);
      // Reading every cell must not dirty anything either.
      for (const ws of wb.worksheets) ws.eachRow((row) => row.eachCell((cell) => void cell.value));

      expect(eq(wb.toBuffer(), bytes)).toBe(true);
      // Stable across repeated reads of the same buffer.
      expect(eq(Workbook.read(bytes).toBuffer(), bytes)).toBe(true);
      expect(eq(Workbook.read(wb.toBuffer()).toBuffer(), bytes)).toBe(true);
    });
  }
});

describe('preservation — a representative edit touches nothing else', () => {
  for (const fixture of FIXTURES) {
    it(`${fixture.file}: value + style + merge change only the sheet and styles.xml`, async () => {
      const bytes = bytesOf(fixture.file);
      const before = Workbook.read(bytes).parts();

      const wb = Workbook.read(bytes);
      const { partName } = representativeEdit(wb);
      const out = wb.toBuffer();

      const after = Workbook.read(out).parts();
      const changed = changedParts(before, after);

      // (a) Every part except the touched sheet and styles.xml is byte-identical.
      expect(changed.sort()).toEqual([partName, 'xl/styles.xml'].sort());
      expect(addedParts(before, after)).toEqual([]);

      // The rich parts are named in the manifest; assert them individually so a
      // regression names the feature that broke.
      for (const part of fixture.richParts) {
        expect(eq(before.get(part)!, after.get(part)!), `rich part changed: ${part}`).toBe(true);
      }

      // Sheet-local features survive the re-serialization of the touched sheet.
      const sheetXml = strFromU8(after.get(partName)!);
      for (const [sheetPart, markers] of Object.entries(fixture.inSheet)) {
        if (sheetPart !== partName) continue;
        for (const marker of markers) {
          expect(sheetXml, `${sheetPart} lost ${marker}`).toContain(marker);
        }
      }
      // The edit itself is there too.
      expect(sheetXml).toContain('<mergeCell ref="H9:J9"');

      // (c) Both independent readers accept the result.
      await expectReReadable(out, fixture.sheets);
      const reread = Workbook.read(out);
      expect(reread.getWorksheet(fixture.sheets[0]!)!.getCell('ZZ100').value).toBe(
        'sheet-lite preservation probe',
      );
      expect(reread.getWorksheet(fixture.sheets[0]!)!.getCell('D9').value).toBe(1234.5);
      expect(reread.getWorksheet(fixture.sheets[0]!)!.getCell('A1').font.bold).toBe(true);
    });
  }
});

describe('preservation — adding a worksheet leaves the rich parts alone', () => {
  for (const fixture of FIXTURES) {
    it(`${fixture.file}: addWorksheet only rewrites the registration parts`, async () => {
      const bytes = bytesOf(fixture.file);
      const before = Workbook.read(bytes).parts();

      const wb = Workbook.read(bytes);
      wb.addWorksheet('Probe').getCell('A1').value = 'added';
      const out = wb.toBuffer();

      const after = Workbook.read(out).parts();

      // Only the parts that register a sheet may change…
      for (const name of changedParts(before, after)) {
        expect(REGISTRATION_PARTS.has(name), `unexpected part rewritten: ${name}`).toBe(true);
      }
      // …plus exactly one new worksheet part.
      const added = addedParts(before, after);
      expect(added).toHaveLength(1);
      expect(added[0]).toMatch(/^xl\/worksheets\/sheet\d+\.xml$/);
      for (const name of added) expect(before.has(name), `overwrote an existing part: ${name}`).toBe(false);

      // (b) Every rich part is still present and byte-identical.
      for (const part of fixture.richParts) {
        expect(after.has(part), `rich part dropped: ${part}`).toBe(true);
        expect(eq(before.get(part)!, after.get(part)!), `rich part changed: ${part}`).toBe(true);
      }
      for (const [sheetPart, markers] of Object.entries(fixture.inSheet)) {
        const xml = strFromU8(after.get(sheetPart)!);
        for (const marker of markers) {
          expect(xml, `${sheetPart} lost ${marker}`).toContain(marker);
        }
      }

      // The file still re-opens, with the new sheet.
      const reread = Workbook.read(out);
      expect(reread.sheetNames).toEqual([...fixture.sheets, 'Probe']);
      expect(reread.getWorksheet('Probe')!.getCell('A1').value).toBe('added');
      await expectReReadable(out, [...fixture.sheets, 'Probe']);
    });
  }
});

describe('preservation — the added-workbook round-trip keeps every feature readable', () => {
  it('table-and-comments: ExcelJS still sees the table and both notes after an edit', async () => {
    const bytes = bytesOf('table-and-comments.xlsx');
    const wb = Workbook.read(bytes);
    representativeEdit(wb);
    const out = wb.toBuffer();

    const ejs = await loadInExcelJs(out);
    const sheet = ejs.getWorksheet('Sales')!;
    // ExcelJS exposes tables through an index getter that is not in its typings.
    const tables = (sheet as unknown as {
      tables: Record<string, { table: { columns: Array<{ name: string }> } }>;
    }).tables;
    expect(Object.keys(tables)).toEqual(['SalesTable']);
    expect(tables.SalesTable!.table.columns.map((column) => column.name)).toEqual([
      'Product',
      'Amount',
      'Note',
    ]);
    expect(typeof sheet.getCell('A1').note).toBe('object');
    expect(JSON.stringify(sheet.getCell('C2').note)).toContain('check this row');
    // Untouched values survived the edit.
    expect(sheet.getCell('A2').value).toBe('Widget');
    expect(sheet.getCell('B4').value).toBe(40);

    const sjs = XLSX.read(out, { type: 'buffer' });
    expect(sjs.Sheets.Sales!.A2.v).toBe('Widget');
  });

  it('image-and-chart: the drawing, the image and the chart survive an added worksheet', async () => {
    const bytes = bytesOf('image-and-chart.xlsx');
    const wb = Workbook.read(bytes);
    wb.addWorksheet('Probe').getCell('A1').value = 'added';
    const out = wb.toBuffer();

    const parts = Workbook.read(out).parts();
    expect(parts.has('xl/media/image1.png')).toBe(true);
    expect(parts.has('xl/charts/chart1.xml')).toBe(true);

    const drawing = strFromU8(parts.get('xl/drawings/drawing1.xml')!);
    expect(drawing).toContain('<xdr:pic>');
    expect(drawing).toContain('r:embed="rId1"');
    expect(drawing).toContain('<xdr:graphicFrame');
    expect(drawing).toContain('r:id="rId2"');

    const chart = strFromU8(parts.get('xl/charts/chart1.xml')!);
    expect(chart).toContain('<c:barChart>');
    expect(chart).toContain('<c:f>Data!$B$2:$B$4</c:f>');

    // The image bytes are the very same 1x1 PNG.
    expect(strFromU8(parts.get('xl/media/image1.png')!.slice(1, 4))).toBe('PNG');

    await expectReReadable(out, ['Data', 'Probe']);
  });

  it('pivot-table: the cache and the pivot table definition survive an edit of the sheet that owns it', async () => {
    const bytes = bytesOf('pivot-table.xlsx');
    const before = Workbook.read(bytes).parts();

    // Edit the Summary sheet — the one whose rels point at the pivot table.
    const wb = Workbook.read(bytes);
    const summary = wb.getWorksheet('Summary')!;
    summary.getCell('B8').value = 999;
    const out = wb.toBuffer();

    const after = Workbook.read(out).parts();
    expect(changedParts(before, after).sort()).toEqual(['xl/worksheets/sheet2.xml']);
    for (const part of [
      'xl/pivotTables/pivotTable1.xml',
      'xl/pivotCache/pivotCacheDefinition1.xml',
      'xl/pivotCache/pivotCacheRecords1.xml',
      'xl/pivotCache/_rels/pivotCacheDefinition1.xml.rels',
      'xl/worksheets/_rels/sheet2.xml.rels',
    ]) {
      expect(eq(before.get(part)!, after.get(part)!), `pivot part changed: ${part}`).toBe(true);
    }
    // The sheet still declares the pivot's relationship.
    expect(strFromU8(after.get('xl/workbook.xml')!)).toContain('<pivotCaches>');
    expect(strFromU8(after.get('xl/worksheets/_rels/sheet2.xml.rels')!)).toContain('pivotTable1.xml');

    await expectReReadable(out, ['Raw', 'Summary']);
    expect(Workbook.read(out).getWorksheet('Summary')!.getCell('B8').value).toBe(999);
  });

  it('validations-and-conditional-formatting: both rules and both validations are still declared', async () => {
    const bytes = bytesOf('validations-and-conditional-formatting.xlsx');
    const wb = Workbook.read(bytes);
    representativeEdit(wb);
    const out = wb.toBuffer();

    const sheetXml = strFromU8(Workbook.read(out).parts().get('xl/worksheets/sheet1.xml')!);
    expect(sheetXml).toContain('<dataValidations count="2">');
    expect(sheetXml).toContain('&quot;red,green,blue&quot;');
    expect(sheetXml).toContain('<dataValidation type="whole"');
    expect(sheetXml).toContain('errorTitle="Out of range"');
    expect(sheetXml).toContain('<conditionalFormatting sqref="B2:B5">');
    expect(sheetXml).toContain('<formula>10</formula>');
    expect(sheetXml).toContain('<cfvo type="percentile" val="50"/>');

    await expectReReadable(out, ['Data']);
  });
});